import{_ as o}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as e}from"./chunks/OFF.BrU7kQE-.js";import{_ as t}from"./chunks/EN.P9aPnFBv.js";import{_ as i}from"./chunks/DIS.DdpTdGGD.js";import{_ as l,o as s,c as n,a3 as r}from"./chunks/framework.g9mfNVRQ.js";const y=JSON.parse('{"title":"Letture vocali","description":"","frontmatter":{"source_hash":null,"source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"it/use/speak.md","filePath":"it/use/speak.md"}'),d={name:"it/use/speak.md"};function p(c,a,m,u,v,_){return s(),n("div",null,[...a[0]||(a[0]=[r('<div class="admonition xdrip"><p class="admonition-title"><img src="'+o+'" style="zoom:75%;"></p><p> Impostazioni<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_speak_reading_grey600_48dp.png" style="width:5%;"> Letture Vocali</p></div><p>Se il tuo telefono supporta la sintesi vocale, xDrip può leggerti ad alta voce vari eventi.</p><div class="admonition xdripitem"><p class="admonition-title">Letture Vocali <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Se il telefono è dotato di lettura vocale, leggerà ogni nuova lettura</p></div><p>Quando attivi la funzione, se la sintesi vocale non è già presente sul dispositivo dovrai installarla dal <a href="https://play.google.com/store/apps/details?id=com.google.android.tts" target="_blank" rel="noreferrer">Google Play Store</a> o dallo store del produttore del telefono.</p><div class="admonition xdripitem"><p class="admonition-title">Installare i dati da sintesi vocale?</p><p>Installare i dati da sintesi vocale?<br> (Dopo l&#39;installazione delle lingue potresti dover premere &quot;Riavvia Collector&quot; in Stato del sistema.)<br> No    OK</p></div><p>Puoi scegliere di ascoltare il valore della glicemia in condizioni specifiche (variazioni oltre una certa soglia) o periodicamente.</p><div class="admonition xdripitem"><p class="admonition-title">Quando cambia di (0 mgdl o mmol/l)</p></div><div class="admonition xdripitem"><p class="admonition-title">Oppure per minuti (0)</p></div><p>Se lo attivi, anche gli avvisi possono essere letti ad alta voce.</p><div class="admonition xdripitem"><p class="admonition-title">Pronuncia allarmi a voce alta <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Fornisci anche alcuni messaggi di avviso vocali</p></div><p>Puoi far pronunciare la tendenza e far ripetere due volte le letture o tutte le informazioni vocali.</p><div class="admonition xdripitem"><p class="admonition-title">Pronuncia a voce alta la freccia di tendenza della glicemia <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Leggi due volte a voce alta il valore del glucosio <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Pronuncia a voce alta due volte <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div><p>Se vuoi forzare le letture in un&#39;altra lingua, puoi selezionarla inserendo manualmente la lingua con il codice <a href="https://en.wikipedia.org/wiki/List_of_ISO_639-1_codes" target="_blank" rel="noreferrer">ISO639-1</a> (ad esempio <code>de</code>) e, facoltativamente, un trattino basso (<code>_</code>) seguito da un&#39;impostazione locale definita secondo <a href="https://en.wikipedia.org/wiki/ISO_3166-1_alpha-2#Officially_assigned_code_elements" target="_blank" rel="noreferrer">ISO3166-1 alpha 2</a> (ad esempio <code>en_IN</code>).</p><div class="admonition xdripitem"><p class="admonition-title">Usa la lingua locale per le letture a voce alta, es: it o en_IN</p></div><p>Puoi modificare il tono della voce e la velocità di lettura.</p><div class="admonition xdripitem"><p class="admonition-title">Velocità della voce</p></div><div class="admonition xdripitem"><p class="admonition-title">Tonalità della voce</p></div><p>E, facoltativamente, aggiungere una scorciatoia al menu principale.</p><div class="admonition xdripitem"><p class="admonition-title">Scorciatoia lettura a voce alta <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Mostra una riga nel menu ☰ per attivare la lettura a voce alta</p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Ultima modifica 23/11/2026</em></a></p>',23)])])}const z=l(d,[["render",p]]);export{y as __pageData,z as default};
